use sha2::{Digest,Sha256};
use std::{fs,path::Path};
fn main(){let mut h=Sha256::new();for p in ["Cargo.toml","Cargo.lock","build.rs","src/lib.rs","src/main.rs","src/publication.rs","src/storage.rs","src/network.rs","src/overlay.rs","src/paper_observer.rs","src/paper_observer/tests.rs","src/tests.rs","../portfolio-engine/src/lib.rs","../dual-no-engine/src/lib.rs","../journal-append/src/lib.rs","../journal-append/src/canonical.rs","../transport-service/src/lib.rs","../transport-service/src/admission.rs","../transport-service/src/credentials.rs","../account-queue/src/main.rs","../src/settlement_value.rs","../src/publication.rs","../src/money.rs"]{println!("cargo:rerun-if-changed={p}");if let Ok(b)=fs::read(Path::new(p)){h.update(p.as_bytes());h.update((b.len() as u64).to_le_bytes());h.update(b)}}let hash=format!("{:x}",h.finalize());println!("cargo:rustc-env=BAAL_SERVICE_ENGINE_HASH={hash}");println!("cargo:rustc-env=BAAL_ENGINE_HASH={hash}");}
